def gcd_sum(n):
    total = 1
    d = 2
    while d * d <= n:
        if n % d == 0:
            a = 0
            while n % d == 0:
                n //= d
                a += 1
            total *= (a + 1) * d**a - a * d**(a - 1)
        d += 1
    if n > 1:
        total *= 2 * n - 1
    return total

def zeros(k):
    z = 0
    q = 5
    while q <= k:
        z += k // q
        q *= 5
    return z


def smallest_k(m):
    lo, hi = 0, 5 * m
    while lo < hi:
        mid = (lo + hi) // 2
        if zeros(mid) >= m:
            hi = mid
        else:
            lo = mid + 1
    return lo
